contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newRoundImplementation) public payable {
        require(newRoundImplementation != address(0), "new implementation must not be zero");

        address ownerBefore = c.owner();
        require(ownerBefore == address(this), "test contract must be the owner");

        bool reverted;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            reverted = false;
